-- Inspeção de estrutura; nenhum dado de carteira. Antes da migração do ciclo 017, os dois indicadores devem ser falsos.
select (select count(*) from information_schema.columns where table_schema='public' and table_name='ativos' and column_name in ('veiculos_acesso','indexadores_remuneracao','regime_tributario','prazo_resgate_tipo','prazo_resgate_dias','prazo_resgate_unidade','cobertura_fgc')) = 7 as colunas_disponiveis, to_regprocedure('public.cadastrar_ativo_com_atributos(text,public.tipo_ajuste,uuid,text,uuid,boolean,boolean,boolean,boolean,text[],text[],text,text,integer,text,text)') is not null and to_regprocedure('public.editar_ativo_com_atributos(uuid,text,uuid,text,uuid,boolean,boolean,boolean,boolean,text[],text[],text,text,integer,text,text)') is not null as funcoes_disponiveis;
